insert into public.zonas (id, nombre, bloque, premium, categoria_emocional, por_que, dato_clinico, evitar_si, orden) values
('trapecio', 'Trapecio', 'Cuello y cabeza', false, true, 'Pasar horas con la cabeza inclinada hacia adelante (celular, computadora) o con los hombros subidos por estrés satura este músculo, que va desde el cráneo hasta la mitad de la espalda. También es la zona clásica donde "guardamos" el estrés: el insomnio, la ansiedad o una época difícil pueden tensarla tanto como una mala postura.', 'Es uno de los músculos que más se contractura en el cuerpo, y su punto de tensión puede generar dolor de cabeza de tipo tensional que sube desde el cuello hacia la sien.', 'Hinchazón marcada, calor o enrojecimiento en la zona; dolor que baja disparado hacia el brazo.', 1),
('suboccipital', 'Suboccipital / Nuca', 'Cuello y cabeza', true, true, 'Son músculos pequeños que sostienen la cabeza en posiciones finas. Mirar el celular hacia abajo o el estrés los acorta y tensiona. El estrés sostenido y la falta de sueño también los contraen, incluso sin una causa postural clara — muchas cefaleas tensionales aparecen así.', 'Generan un patrón de dolor referido muy característico: empieza en la nuca y sube hacia la frente o las sienes, muy similar a una cefalea tensional.', 'Mareo al presionar, dolor que se dispara con la presión, cualquier golpe reciente en la zona.', 2),
('temporal', 'Cuero cabelludo / sien (temporal)', 'Cuello y cabeza', true, false, 'El músculo temporal, en el costado de la cabeza, ayuda a cerrar la mandíbula. Se sobrecarga por apretar los dientes o por tensión general del estrés.', 'Los dolores de cabeza tipo "banda de presión" en el costado de la cabeza suelen originarse en el temporal, no en el cuero cabelludo como tal.', 'Heridas o infecciones en el cuero cabelludo, dolor de cabeza súbito y muy intenso (requiere evaluación médica).', 3),
('mandibula', 'Mandíbula (ATM / masetero)', 'Cuello y cabeza', true, true, 'El estrés y el bruxismo (apretar o rechinar los dientes) sobrecargan el masetero, el músculo principal para cerrar la mandíbula. El bruxismo casi siempre tiene una raíz emocional: ansiedad, estrés acumulado o una etapa de mucha exigencia personal.', 'El automasaje no alcanza los músculos más profundos de la mandíbula, por eso si hay chasquidos, bloqueos o dolor fuerte al abrir la boca, se necesita evaluación profesional.', 'Chasquidos o bloqueo al abrir la boca, dolor dental agudo, cirugía dental reciente.', 4),
('hombro', 'Hombro (deltoides)', 'Espalda', true, false, 'Los deltoides rodean la articulación del hombro y se sobrecargan al cargar peso o mantener los brazos elevados mucho tiempo.', 'Trabajar el deltoides de forma longitudinal y lento reduce la hiperactividad muscular y calma las señales de dolor.', 'Hombro congelado diagnosticado, luxación reciente, dolor agudo al levantar el brazo.', 5),
('omoplatos', 'Omóplatos (romboides / escápula)', 'Espalda', true, false, 'Es la zona típica de "cargar la mochila del estrés" — se tensiona por mantener los hombros hacia adelante frente a la computadora.', 'Trabajar esta zona con las manos ayuda a liberar también estructuras cercanas al manguito rotador, mejorando la movilidad del hombro.', 'Nunca presionar directo sobre el borde óseo de la escápula, solo sobre el músculo.', 6),
('dorsal', 'Dorsal / zona alta de la espalda', 'Espalda', true, false, 'Las horas de mala postura frente a la pantalla cargan esta zona ancha de la espalda, que conecta el hombro con la zona lumbar.', 'El automasaje de esta zona alcanza el redondo mayor y el dorsal ancho — trabajar despacio y profundo con los nudillos da mayor beneficio que un pase rápido.', 'Dolor agudo tipo "punzada" al respirar hondo (puede ser otra causa, no muscular).', 7),
('lumbar', 'Lumbar (incluye cuadrado lumbar)', 'Espalda', false, true, 'Es de las zonas que más carga acumula por estar sentado muchas horas o cargar peso con mala postura. El cuadrado lumbar es el músculo detrás del típico "dolor de riñones". La tensión emocional sostenida (preocupación constante, ansiedad) también se acumula aquí, incluso sin haber cargado peso ni pasado horas sentada.', 'El automasaje lumbar se trabaja siempre a los lados de la columna (nunca sobre ella), con movimientos lentos, entre 3 y 6 minutos por lado.', 'Dolor que baja como un rayo hacia la pierna (posible compromiso del nervio ciático) — ahí no se automasajea, se consulta primero.', 8),
('piriforme', 'Glúteo / Piriforme', 'Cadera y glúteo', false, false, 'El piriforme es un músculo pequeño y profundo del glúteo. Al contracturarse, puede atrapar el nervio ciático.', 'Genera un patrón de dolor referido hacia la pierna muy parecido al de una hernia discal, sin serlo — se le conoce como "falsa ciática".', 'Dolor punzante y agudo al presionar (bajar la intensidad de inmediato), hernia discal sin autorización médica.', 9),
('pantorrillas', 'Pantorrillas', 'Piernas y pies', false, false, 'Estar mucho tiempo de pie o sentado hace que la circulación de retorno trabaje peor, y la pantorrilla es el músculo que más ayuda a bombear la sangre de vuelta al corazón.', 'Por esta función de bombeo se le conoce como "el segundo corazón" — trabajarla siempre en dirección ascendente ayuda a esa circulación de retorno.', 'Hinchazón marcada de un solo lado, calor local o dolor que no calza con cansancio normal — puede ser un tema circulatorio.', 10),
('planta_pie', 'Planta del pie', 'Piernas y pies', true, false, 'La fascia plantar sostiene el arco del pie y se sobrecarga por estar de pie muchas horas, calzado plano, o pantorrillas muy tensas.', 'Combinar el trabajo de la planta del pie con automasaje en la pantorrilla mejora el resultado, porque están conectadas.', 'Dolor agudo al primer paso de la mañana de forma repetida (trabajar con suavidad y consultar si no mejora).', 11),
('antebrazo', 'Antebrazo (extensores y flexores)', 'Brazo, antebrazo y mano', false, false, 'El uso de mouse y teclado sobrecarga el lado de arriba del antebrazo (extensores); escribir y cargar cosas sobrecarga el lado de abajo (flexores).', 'Cuando se inflama la inserción en el codo, del lado extensor es "codo de tenista" y del lado flexor es "codo de golfista" — son distintas y no se tratan igual.', 'Hormigueo, adormecimiento o "corrientazo" hacia los dedos (posible nervio comprometido).', 12),
('mano_muneca', 'Mano y muñeca', 'Brazo, antebrazo y mano', true, false, 'El uso constante del celular y el teclado sobrecarga los músculos pequeños de la palma y los dedos.', 'El hormigueo hacia pulgar/índice/medio puede indicar compromiso del nervio mediano en la muñeca — ahí no se automasajea, se consulta.', 'Hormigueo o adormecimiento hacia los dedos, hinchazón marcada en la muñeca.', 13),
('pectorales', 'Pectorales', 'Brazo, antebrazo y mano', true, false, 'Mantener los hombros hacia adelante frente a la pantalla tensiona y acorta este músculo.', 'Está muy relacionado con el dolor de hombro y la postura general — trabajarlo ayuda también a mejorar dolores cervicales.', 'Cualquier dolor en el pecho que no sea claramente muscular (opresión, falta de aire) requiere atención médica inmediata, no automasaje.', 14),
('abdomen', 'Abdomen', 'Brazo, antebrazo y mano', true, true, 'El estrés y estar sentado muchas horas afectan también el tránsito intestinal. Las emociones que se "guardan" sin procesar —ansiedad, preocupación, tristeza— afectan directamente la digestión: es una de las zonas donde el cuerpo somatiza de forma más clara.', 'El masaje abdominal es una herramienta real usada en fisioterapia para el estreñimiento, siguiendo el sentido del colon (como una "C" invertida), con presión suave.', 'Embarazo, dolor abdominal agudo, justo después de comer (esperar 1-2 horas), cualquier diagnóstico digestivo sin autorización médica.', 15);
